    cr,cc=next((r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==3)
    # Relative mask directly transcribed from demo 2 around its seed at (5,5).
    mask=['...........', '...3333333.', '...3.....3.', '...3.333.3.', '.3.3.3.3.3.', '.3.3.3.3.3.', '.3.3...3.3.', '.3.33333.3.', '.3.......3.', '.333333333.', '...........']
    out=[row[:] for row in grid]
    for r in range(11):
        for c in range(11):
            rr,cc2=cr+r-5,cc+c-5
            if mask[r][c]=='3' and 0<=rr<h and 0<=cc2<w and grid[rr][cc2]==0:
